            listing = others[0] if len(others) == 1 else f"{', '.join(others[:-1])} and {others[-1]}"
            verdict += f" Also supported by {listing}."
        verdict += (f" {pc(assumption)} of the score rests on trend assumptions." if assumption > 0.005
