  { brand: "Zeekr", pattern: /Zeekr|极氪/i },
  { brand: "BYD", pattern: /\bBYD\b|比亚迪|仰望|方程豹|腾势|Denza/i },
  { brand: "BMW", pattern: /\bBMW\b|宝马/i },
